            }
        }
        return false;
    }
    private boolean sameCohort(
            int first,
            int second,
            int target,
            int population) {
        if (first == second) {
            return false;
        }
        int preferredSize = target + 1;
        int cohortCount =
                (population + preferredSize / 2)
                        / preferredSize;
        if (cohortCount < 1) {
            cohortCount = 1;
        }
        return cohortOf(
                first, population, cohortCount)
                == cohortOf(
                        second, population, cohortCount);
    }
    private int cohortOf(
            int actor,
            int population,
            int cohortCount) {
        int smallSize = population / cohortCount;
        int largeCount = population % cohortCount;
        int largeRegion =
                largeCount * (smallSize + 1);
